INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7558859, 1211523, 41129, '<td valign="top">Corkscrew.</td>', 'Corkscrew.', '2018-02-11 20:54:49.000000', NULL, 1),
(7558957, 1210823, 56502, '<td valign="top">A phone jack - interesting background, and also the somewhat dynamic presentation appeals to me.</td>', 'A phone jack - interesting background, and also the somewhat dynamic presentation appeals to me.', '2018-02-12 10:31:40.000000', NULL, 1),
(7558958, 1211539, 56502, '<td valign="top">These must be the eggshells after some alien species hatched.</td>', 'These must be the eggshells after some alien species hatched.', '2018-02-12 10:34:23.000000', NULL, 1),
(7558963, 1211413, 56502, '<td valign="top">I never thought much about fishing, but looking at that I think it''s kind of brutal - imagine how it feels to bite into that! Looking at your shot I can almost feel the pain!</td>', 'I never thought much about fishing, but looking at that I think it''s kind of brutal - imagine how it feels to bite into that! Looking at your shot I can almost feel the pain!', '2018-02-12 10:41:19.000000', NULL, 1),
(7558964, 1211477, 56502, '<td valign="top">Looks a bit like a cartoon of a laughing ape :-)</td>', 'Looks a bit like a cartoon of a laughing ape :-)', '2018-02-12 10:42:45.000000', NULL, 1),
(7558967, 1211512, 56502, '<td valign="top">Very detailed. No idea what it was used for.</td>', 'Very detailed. No idea what it was used for.', '2018-02-12 10:44:03.000000', NULL, 1),
(7558968, 1211508, 56502, '<td valign="top">No idea what it is but I like the pleasant forms and reflections.</td>', 'No idea what it is but I like the pleasant forms and reflections.', '2018-02-12 10:45:31.000000', NULL, 1),
(7558969, 1211035, 56502, '<td valign="top">The drop supplements it well - without it I think it would look somewhat boring.</td>', 'The drop supplements it well - without it I think it would look somewhat boring.', '2018-02-12 10:49:22.000000', NULL, 1),
(7558973, 1211501, 56502, '<td valign="top">This must be a collection of dandruffs.</td>', 'This must be a collection of dandruffs.', '2018-02-12 10:51:33.000000', NULL, 1),
(7558975, 1211533, 56502, '<td valign="top">Didn''t know that there are toy spike strips these days. Well lit!</td>', 'Didn''t know that there are toy spike strips these days. Well lit!', '2018-02-12 10:55:55.000000', NULL, 1),
(7558977, 1211510, 56502, '<td valign="top">My guess: vitamine capsules. A, D, E, take your choice.</td>', 'My guess: vitamine capsules. A, D, E, take your choice.', '2018-02-12 11:03:15.000000', NULL, 1),
(7558978, 1211507, 56502, '<td valign="top">Something like that covers the little speakers on my desk. So some sort of cover.</td>', 'Something like that covers the little speakers on my desk. So some sort of cover.', '2018-02-12 11:05:50.000000', NULL, 1),
(7558979, 1211502, 56502, '<td valign="top">A roll of carpet?</td>', 'A roll of carpet?', '2018-02-12 11:07:27.000000', NULL, 1),
(7558980, 1211403, 56502, '<td valign="top">Dandelion seeds? It looks like it''s glowing!</td>', 'Dandelion seeds? It looks like it''s glowing!', '2018-02-12 11:08:42.000000', NULL, 1),
(7558981, 1211523, 56502, '<td valign="top">Cork screw.</td>', 'Cork screw.', '2018-02-12 11:10:58.000000', NULL, 1),
(7558994, 1210966, 56502, '<td valign="top">Fascinating - it looks so huge as if it were an elephant!</td>', 'Fascinating - it looks so huge as if it were an elephant!', '2018-02-12 11:57:57.000000', NULL, 1),
(7558996, 1211476, 56502, '<td valign="top">I guess it''s the thingy that is used to tune a string instrument (or piano).<br/>Very 3-D, well lit - one of my favorites in this challenge.</td>', 'I guess it''s the thingy that is used to tune a string instrument (or piano).Very 3-D, well lit - one of my favorites in this challenge.', '2018-02-12 12:00:24.000000', NULL, 1),
(7558999, 1211500, 56502, '<td valign="top">I''d think it''s something like the cable that is used to connect a hard disk to the main board - those I know are just of a boring grey, though. I love the airy colors!</td>', 'I''d think it''s something like the cable that is used to connect a hard disk to the main board - those I know are just of a boring grey, though. I love the airy colors!', '2018-02-12 12:03:11.000000', NULL, 1),
(7559038, 1211521, 56502, '<td valign="top">Must be something stylish. Even that detail looks elegant.</td>', 'Must be something stylish. Even that detail looks elegant.', '2018-02-12 15:04:07.000000', NULL, 1),
(7559039, 1211398, 56502, '<td valign="top">Fabric in sparkling water? Anyway interesting effect, looks kind of cool.</td>', 'Fabric in sparkling water? Anyway interesting effect, looks kind of cool.', '2018-02-12 15:05:13.000000', NULL, 1),
(7559040, 1211528, 56502, '<td valign="top">I guess it''s an eggbeater. Good contrast.</td>', 'I guess it''s an eggbeater. Good contrast.', '2018-02-12 15:05:18.000000', NULL, 1),
(7559041, 1211517, 56502, '<td valign="top">No idea - broken plexiglass in polarized light?</td>', 'No idea - broken plexiglass in polarized light?', '2018-02-12 15:06:48.000000', NULL, 1),
(7559042, 1211222, 56502, '<td valign="top">Maybe rubberbands.</td>', 'Maybe rubberbands.', '2018-02-12 15:07:50.000000', NULL, 1),
(7559043, 1211121, 56502, '<td valign="top">I could imagine it''s one of these cat toys.</td>', 'I could imagine it''s one of these cat toys.', '2018-02-12 15:08:03.000000', NULL, 1),
(7559045, 1211480, 56502, '<td valign="top">Yarn in front of a wall would be my guess. A bit too close to the edge for my personal taste.</td>', 'Yarn in front of a wall would be my guess. A bit too close to the edge for my personal taste.', '2018-02-12 15:09:49.000000', NULL, 1),
(7559046, 1210865, 56502, '<td valign="top">Some rusty metal. What''s the whole thing? Interesting mystery.</td>', 'Some rusty metal. What''s the whole thing? Interesting mystery.', '2018-02-12 15:10:54.000000', NULL, 1),
